 $('#memory').innerHTML=table(['组成','GiB/rank'],rows.map(([a,b])=>[a,num(b)]));$('#memory-bars').innerHTML=rows.filter(v=>v[1]>0).map(([a,b])=>`<div class="bar"><span>${esc(a)}</span><i style="width:${Math.max(1,b/r.totalGiB*160)}px"></i><b>${num(b)}</b></div>`).join('');
 const times=[['MoE dispatch+combine/微批',r.moeBytes/1e9,r.a2aSeconds],['TP collectives/微批',r.tpBytes/1e9,r.tpSeconds],['DP梯度+ZeRO gather/迭代', (r.dpBytes+r.gatherBytes)/1e9,r.dpSeconds],['PP传输/微批',r.ppBytes/1e9,r.ppSeconds]];
