function exportCsv(){const rows=[['类别','字段','数值','口径'],['模型','id',m.id,'修改输入后均为用户情景'],...Object.entries(m).map(([k,v])=>['模型',k,v,'参数计数为元素']),...Object.entries(x).map(([k,v])=>['输入',k,v,'见网页单位与公式说明']),...Object.entries(result).map(([k,v])=>['结果',k,Array.isArray(v)?JSON.stringify(v):v&&typeof v==='object'?JSON.stringify(v):v,'无设备实测'])];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=m.id+'-supernode-scenario.csv';a.click();URL.revokeObjectURL(a.href);}
