 $('#inputs').addEventListener('input',update);$('#model').onchange=loadModel;$('#hardware').onchange=loadHardware;$('#format').onchange=update;$('#act-format').onchange=update;$('#grad-sync').onchange=update;$('#cache-layout').onchange=update;$('#phase').onchange=()=>{if($('#phase').value==='lora')$('#format').value='BF16';if($('#phase').value==='qlora')$('#format').value='NF4';update()};$('#export').onclick=exportCsv;
